CREATE OR REPLACE FUNCTION public.record_wave_demand() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE line jsonb; label text; stocked boolean; BEGIN FOR line IN SELECT * FROM jsonb_array_elements(NEW.items) LOOP SELECT name INTO label FROM catalog_items WHERE id=line->>'id'; stocked:=EXISTS(SELECT 1 FROM stock WHERE item_id=line->>'id' AND available AND quantity>0); INSERT INTO demand(key,item_id,label,requests,unfilled,last_at) VALUES(line->>'id',line->>'id',coalesce(label,line->>'id'),1,CASE WHEN stocked THEN 0 ELSE 1 END,now()) ON CONFLICT(key) DO UPDATE SET requests=demand.requests+1,unfilled=demand.unfilled+excluded.unfilled,last_at=now(); END LOOP; IF trim(NEW.wish)<>'' THEN INSERT INTO demand(key,label,requests,unfilled,last_at) VALUES('wish:'||lower(trim(NEW.wish)),trim(NEW.wish),1,1,now()) ON CONFLICT(key) DO UPDATE SET requests=demand.requests+1,unfilled=demand.unfilled+1,last_at=now(); END IF; RETURN NEW; END $$; CREATE TRIGGER record_wave_demand AFTER INSERT ON waves FOR EACH ROW EXECUTE FUNCTION public.record_wave_demand();
CREATE OR REPLACE FUNCTION public.restore_cancelled_stock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE line jsonb; BEGIN IF OLD.cancelled_at IS NULL AND NEW.cancelled_at IS NOT NULL THEN FOR line IN SELECT * FROM jsonb_array_elements(NEW.items) LOOP UPDATE stock SET quantity=quantity+(line->>'qty')::integer WHERE id=(SELECT id FROM stock WHERE trader_id=NEW.trader_id AND item_id=line->>'id' ORDER BY id LIMIT 1); END LOOP; END IF; RETURN NEW; END $$; CREATE TRIGGER restore_cancelled_stock AFTER UPDATE OF cancelled_at ON wave_orders FOR EACH ROW EXECUTE FUNCTION public.restore_cancelled_stock();
CREATE OR REPLACE FUNCTION public.save_settlement_once() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO savings_pots(user_id,balance) VALUES(NEW.trader_id,round(NEW.net*0.05,2)) ON CONFLICT(user_id) DO UPDATE SET balance=savings_pots.balance+excluded.balance,updated_at=now(); RETURN NEW; END $$; CREATE TRIGGER save_settlement_once AFTER INSERT ON settlements FOR EACH ROW EXECUTE FUNCTION public.save_settlement_once();
